      poverty_cv < 12 ~ "🟢",
      poverty_cv <= 40 ~ "🟡",
      TRUE ~ "🔴"
    ),
    flag = case_when(
      is.na(poverty_cv) ~ "Not available",
      poverty_cv < 12 ~ "Reliable",
      poverty_cv <= 40 ~ "Somewhat reliable",
      TRUE ~ "Unreliable"
    )
  ) |> 
  arrange(desc(poverty_cv)) |> 
  select(
    dot,
    NAME,
    totalE,
    belowE,
    poverty_rt,
    poverty_moe,
    poverty_cv,
    flag
  )

reliability_table_2017 |> 
  gt() |> 
  fmt_number(
    columns = c(totalE, belowE),
    decimals = 0
  ) |> 
  fmt_number(
    columns = poverty_rt,
    decimals = 1,
    scale_by = 100
  ) |> 
  fmt_number(
    columns = poverty_moe,
    decimals = 3
  ) |> 
  fmt_number(
    columns = poverty_cv,
    decimals = 1
  ) |> 
  cols_label(
    dot = "",
    NAME = "Census Tract",
    totalE = "Population",
    belowE = "Below Poverty",
    poverty_rt = "Poverty Rate (%)",
    poverty_moe = "MOE",
    poverty_cv = "CV (%)",
    flag = "Reliability"
  ) |> 
  cols_align(
    align = "center",
    columns = dot
  ) |> 
  tab_header(
    title = "Reliability of Philadelphia Census Tract Poverty Rates",
    subtitle = "ACS 2013–2017 5-year estimates"
  ) |> 
  tab_source_note(
    "Reliability thresholds follow Jurjevich et al. (2018): CV < 12% reliable, 12–40% somewhat reliable, > 40% unreliable."
  )
